  'mvc': ['csharp', 'dotnet'],
  'wcf': ['csharp', 'dotnet'],
  'entity_framework': ['csharp', 'dotnet'],
  'webapi': ['csharp', 'dotnet'],
  'kubernetes': ['docker'],
  'gitlab': ['git'],
  'github': ['git'],
  'tfs': ['git'],
};

// ============================================================================
// ФУНКЦИИ
// ============================================================================

function cleanRtfText(rtfText) {
  if (!rtfText) return '';

  let text = rtfText;

  // Удаляем RTF control words
  text = text.replace(/\\[a-z]+\d*\s?/g, '');

  // Удаляем фигурные скобки
  text = text.replace(/[{}]/g, '');

  // Удаляем escape-последовательности
  text = text.replace(/\\'[0-9a-fA-F]{2}/g, '');

  // Удаляем обратные слеши
  text = text.replace(/\\/g, '');

  // Заменяем множественные пробелы на одиночные
  text = text.replace(/\s+/g, ' ');

  // Trim
  text = text.trim();

  return text;
}

function extractSkills(text, patterns) {
  const found = new Set();

  for (const [skillName, pattern] of Object.entries(patterns)) {
    if (pattern.test(text)) {
      found.add(skillName);
    }
  }

  return found;
}

function extractExperienceYears(text) {
  const years = [];

  for (const pattern of EXPERIENCE_PATTERNS) {
    const matches = [...text.matchAll(pattern)];
    for (const match of matches) {
      const year = parseInt(match[1]);
      if (!isNaN(year)) {
        years.push(year);
      }
    }
  }

  return years.length > 0 ? Math.max(...years) : 0;
}

function extractEducationLevel(text) {
  const levelScores = {
    'phd': 3,
    'master': 2,
    'bachelor': 1
  };

  for (const [level, pattern] of Object.entries(EDUCATION_LEVELS)) {
    if (pattern.test(text)) {
      return levelScores[level];
    }
  }

  return 0;
}

function extractAllTargets(text) {
  const result = {};

  // Извлекаем навыки по категориям
  for (const [categoryName, patterns] of Object.entries(SKILL_CATEGORIES)) {
    result[categoryName] = extractSkills(text, patterns);
  }

  // Извлекаем опыт и образование
  result.experience_years = extractExperienceYears(text);
  result.education_level = extractEducationLevel(text);

  // === ИЗМЕНЕНИЕ: primary_language ===
  result.primary_language = result.programming_languages.size > 0
    ? Array.from(result.programming_languages)[0]
    : null;

  return result;
}

function expandSkills(targets) {
  const expanded = {};

  for (const [category, skills] of Object.entries(targets)) {
    if (skills instanceof Set) {
      const expandedSet = new Set(skills);

      // Добавляем родительские навыки из иерархии
      for (const skill of skills) {
        if (SKILL_HIERARCHY[skill]) {
          for (const parentSkill of SKILL_HIERARCHY[skill]) {
            expandedSet.add(parentSkill);
          }
        }
      }

      expanded[category] = expandedSet;
    } else {
      expanded[category] = skills;
    }
  }

  return expanded;
}

function formatTargets(targets) {
  const formatted = {};

  for (const [key, value] of Object.entries(targets)) {
    if (value instanceof Set) {
      formatted[key] = Array.from(value).sort();
    } else {
      formatted[key] = value;
    }
  }

  return formatted;
}

// ============================================================================
// ОСНОВНАЯ ЛОГИКА
// ============================================================================

// NEW: универсально извлекаем chatId из Telegram Trigger (не только message)
const tg = $node["Telegram Trigger"]?.json ?? {};
const chatId =
  tg.message?.chat?.id ??
  tg.edited_message?.chat?.id ??
  tg.callback_query?.message?.chat?.id ??
  tg.channel_post?.chat?.id ??
  tg.edited_channel_post?.chat?.id ??
  tg.my_chat_member?.chat?.id ??
  tg.chat_member?.chat?.id ??
  tg.chat_join_request?.chat?.id ??
  // fallback: иногда можно взять хотя бы from.id (для лички часто совпадает, но лучше иметь chat.id)
  tg.message?.from?.id ??
  tg.callback_query?.from?.id ??
  null;

const items = $input.all();
const results = [];

for (const item of items) {
  // Получаем текст вакансии из поля 'data'
  const vacancyText = item.json.data || '';

  if (!vacancyText) {
    results.push({
      json: {
        chatId, // NEW
        success: false,
        error: 'No data field found',
        targets: null
      }
    });
    continue;
  }

  try {
    // Шаг 1: Очищаем RTF
    const cleanText = cleanRtfText(vacancyText);

    // Шаг 2: Извлекаем таргеты
    let targets = extractAllTargets(cleanText);

    // Шаг 3: Расширяем навыки по иерархии
    targets = expandSkills(targets);

    // Шаг 4: Форматируем для JSON (Set -> Array)
    const formattedTargets = formatTargets(targets);

    // Шаг 5: Создаем сводку
    const totalSkills = Object.entries(formattedTargets)
      .filter(([key]) => !['experience_years', 'education_level', 'primary_language'].includes(key))
      .reduce((sum, [, skills]) => sum + skills.length, 0);

    const summary = {
      total_skills_found: totalSkills,
      programming_languages_count: formattedTargets.programming_languages?.length || 0,
      frameworks_count: formattedTargets.frameworks?.length || 0,
      databases_count: formattedTargets.databases?.length || 0,
      devops_tools_count: formattedTargets.devops_tools?.length || 0,
      operating_systems_count: formattedTargets.operating_systems?.length || 0,
      methodologies_count: formattedTargets.methodologies?.length || 0,
      experience_required_years: formattedTargets.experience_years || 0,
      education_level: formattedTargets.education_level || 0,
      primary_language: formattedTargets.primary_language || null
    };

    // Формируем результат
    results.push({
      json: {
        chatId, // NEW
        success: true,
        targets: formattedTargets,
        summary: summary,
        debug_info: {
          original_length: vacancyText.length,
          cleaned_length: cleanText.length,
          clean_preview: cleanText.substring(0, 200) + (cleanText.length > 200 ? '...' : '')
        }
      }
    });

  } catch (error) {
    results.push({
      json: {
        chatId, // NEW
        success: false,
        error: error.message,
        error_type: error.name,
        targets: null
      }
    });
  }
}

return results;

// Get the output from AI Agent
const ai = $input.first().json ?? {};

// Extract chatId from Telegram Trigger using proper n8n expression syntax
const chatId = $('Telegram Trigger').item.json.message?.chat?.id ?? null;

// Return one item: output + chatId
return [{ json: { ...ai, chatId } }];

// ============================================================================
// Извлечение навыков из вакансии + подготовка query для эмбеддинга
// ============================================================================

const DATABASES = {
  'mysql': /\bmysql\b/i,
  'postgresql': /\b(?:postgresql|postgres)\b/i,
  'sqlite': /\bsqlite\b/i,
  'oracle': /\boracle(?:\s+db)?\b/i,
  'mssql': /\b(?:ms\s*sql|sql\s*server|mssql)\b/i,
  'mongodb': /\bmongodb?\b/i,
  'redis': /\bredis\b/i,
  'elasticsearch': /\belastic\s*search\b/i,
  'cassandra': /\bcassandra\b/i,
  'dynamodb': /\bdynamodb\b/i,
  'mariadb': /\bmariadb\b/i
};

const PROGRAMMING_LANGUAGES = {
  'python': /\bpython\b/i,
  'java': /\bjava(?!script)\b/i,
  'javascript': /\b(?:javascript|js)\b/i,
  'typescript': /\btypescript\b/i,
  'csharp': /\b(?:c#|csharp|c\s*sharp)\b/i,
  'cpp': /\b(?:c\+\+|cpp)\b/i,
  'go': /\b(?:golang|go\s+lang)\b/i,
  'ruby': /\bruby\b/i,
  'php': /\bphp\b/i,
  'sql': /\bsql\b/i
};

const FRAMEWORKS = {
  'react': /\breact(?:\.?js)?\b/i,
  'angular': /\bangular(?:\.?js)?\b/i,
  'vue': /\bvue(?:\.?js)?\b/i,
  'nodejs': /\bnode\.?js\b/i,
  'express': /\bexpress(?:\.?js)?\b/i,
  'django': /\bdjango\b/i,
  'flask': /\bflask\b/i,
  'spring': /\bspring(?:\s*boot)?\b/i,
  'dotnet': /\b(?:\.net|dotnet|asp\.?net)\b/i,
  'docker': /\bdocker\b/i,
  'kubernetes': /\b(?:kubernetes|k8s)\b/i,
  'aws': /\b(?:aws|amazon\s+web\s+services)\b/i
};

function cleanText(text) {
  if (!text) return '';
  let t = text;
  t = t.replace(/\\[a-z]+\d*\s?/g, '');
  t = t.replace(/[{}]/g, '');
  t = t.replace(/\\'[0-9a-fA-F]{2}/g, '');
  t = t.replace(/\\\\/g, '');
  t = t.replace(/\s+/g, ' ');
  return t.trim();
}

function extract(text, patterns) {
  const found = [];
  for (const [name, pat] of Object.entries(patterns)) {
    if (pat.test(text)) found.push(name);
  }
  return found;
}

const tg = $('Telegram Trigger').item.json;
const chatId = tg.message?.chat?.id ?? null;

const rawText = $input.first().json.data || '';
const vacancyText = cleanText(rawText);

const databases = extract(vacancyText, DATABASES);
const languages = extract(vacancyText, PROGRAMMING_LANGUAGES);
const frameworks = extract(vacancyText, FRAMEWORKS);

const skillsSummary = [
  languages.length > 0 ? `Languages: ${languages.join(', ')}` : '',
  frameworks.length > 0 ? `Frameworks: ${frameworks.join(', ')}` : '',
  databases.length > 0 ? `Databases: ${databases.join(', ')}` : ''
].filter(Boolean).join('; ');

return [{
  json: {
    chatId,
    vacancy_text: vacancyText.substring(0, 4000),
    vacancy_databases: databases,
    vacancy_languages: languages,
    vacancy_frameworks: frameworks,
    skills_summary: skillsSummary
  }
}];

const vacancy = $('Parse Vacancy').item.json;
const response = $input.first().json;

const vector = response.data[0].embedding;

return [{
  json: {
    chatId: vacancy.chatId,
    vacancy_text: vacancy.vacancy_text,
    skills_summary: vacancy.skills_summary,
    vacancy_databases: vacancy.vacancy_databases,
    vector
  }
}];

// ============================================================================
// Stage 1: Обработка результатов Pinecone → top-5 для реранкера
// ============================================================================

const vacancy = $('Prepare Vector').item.json;
const pineconeRaw = $input.first().json;

const matches = pineconeRaw.matches || [];

if (matches.length === 0) {
  return [{
    json: {
      chatId: vacancy.chatId,
      error: true,
      output: '\u274C В базе Pinecone не найдено подходящих резюме.'
    }
  }];
}

const candidates = matches.map((m, idx) => {
  const meta = m.metadata || {};
  return {
    rank: idx + 1,
    id: m.id,
    score: (m.score || 0).toFixed(3),
    cv_text: meta.text || meta.content || meta.pageContent || meta.doc || JSON.stringify(meta),
    cv_name: meta.name || meta.filename || meta.title || meta.source || m.id
  };
});

const topN = candidates.slice(0, 5);

const stage1List = topN.map(c =>
  `${c.rank}. ${c.cv_name} (score: ${c.score})`
);

return [{
  json: {
    chatId: vacancy.chatId,
    error: false,
    vacancy_text: vacancy.vacancy_text,
    skills_summary: vacancy.skills_summary,
    vacancy_databases: vacancy.vacancy_databases,
    topN,
    remaining: candidates.slice(5),
    stage1_list: stage1List,
    total_found: candidates.length
  }
}];

const data = $input.first().json;

if (data.error) {
  return [{ json: data }];
}

const candidateDescriptions = data.topN.map((c, i) =>
  `### Кандидат ${i + 1} (ID: ${c.id})\nИмя: ${c.cv_name}\nPinecone score: ${c.score}\n\nРезюме (фрагмент):\n${(c.cv_text || '').substring(0, 800)}`
).join('\n\n---\n\n');

const prompt = `Ты опытный технический рекрутер. Тебе дана вакансия и ${data.topN.length} кандидатов-финалистов, найденных в базе резюме.

Задача: расставь кандидатов от наиболее подходящего к наименее подходящему для данной вакансии.

Учитывай:
- Совпадение технического стека (языки, фреймворки, БД, DevOps)
- Уровень и релевантность опыта
- Специализацию кандидата vs требования вакансии
- Базы данных особенно важны для оценки

## Вакансия:
${data.vacancy_text.substring(0, 2000)}

Извлечённые навыки вакансии: ${data.skills_summary}

## Кандидаты-финалисты:
${candidateDescriptions}

Ответь СТРОГО в формате JSON без markdown-обёрток:
{
  "ranking": ["ID_лучшего", "ID_второго", "ID_третьего", ...],
  "reasoning": "краткое обоснование на русском, 2-3 предложения",
  "top1_details": "почему первый кандидат лучше всего подходит, 1-2 предложения"
}`;

return [{
  json: {
    chatId: data.chatId,
    error: false,
    prompt,
    topN: data.topN,
    remaining: data.remaining,
    stage1_list: data.stage1_list,
    total_found: data.total_found,
    skills_summary: data.skills_summary
  }
}];

// Get the output from AI Agent
const ai = $input.first().json ?? {};

// Extract chatId from Telegram Trigger using proper n8n expression syntax
const chatId = $('Telegram Trigger').item.json.message?.chat?.id ?? null;

// Return one item: output + chatId
return [{ json: { ...ai, chatId } }];
